   803
   804          }
   805          else                         // Is a number?
   806              if (isdigit(it8->ch) || it8->ch == '.' || it8->ch == '-' || it8->ch == '+')
   807              {
   808                  int sign = 1;
   809
   810                  if (it8->ch == '-') {
