   816                  it8->sy   = SINUM;
   817
   818                  if (it8->ch == '0') {          // 0xnnnn (Hexa) or 0bnnnn (Binary)
   819
   820                      NextCh(it8);
   821                      if (toupper(it8->ch) == 'X') {
   822
   823                          int j;
   824
   825                          NextCh(it8);
