   840                          }
   841                          return;
   842                      }
   843
   844                      if (toupper(it8->ch) == 'B') {  // Binary
   845
   846                          int j;
   847
   848                          NextCh(it8);
   849                          while (it8->ch == '0' || it8->ch == '1')
   850                          {
   851                              j = it8->ch - '0';
   852
   853                              if ((cmsFloat64Number) it8->inum * 2.0 + j > (cmsFloat64Number)+2147483647.0)
