   855                                  SynError(it8, "Invalid binary number");
   856                                  return;
   857                              }
   858
   859                              it8->inum = it8->inum * 2 + j;
   860                              NextCh(it8);
   861                          }
   862                          return;
   863                      }
   864                  }
   865
   866
   867                  while (isdigit(it8->ch)) {
   868
   869                      cmsInt32Number digit = (it8->ch - '0');
   870
   871                      if ((cmsFloat64Number) it8->inum * 10.0 + (cmsFloat64Number) digit > (cmsFloat64Number) +2147483647.0) {
