  1804  // Writes the data format
  1805  static
  1806  void WriteDataFormat(SAVESTREAM* fp, cmsIT8* it8)
  1807  {
  1808      int i, nSamples;
  1809      TABLE* t = GetTable(it8);
  1810
  1811      if (!t -> DataFormat) return;
  1812
  1813         WriteStr(fp, "BEGIN_DATA_FORMAT\n");
  1814         WriteStr(fp, " ");
  1815         nSamples = satoi(cmsIT8GetProperty(it8, "NUMBER_OF_FIELDS"));
  1816
  1817         for (i = 0; i < nSamples; i++) {
  1818
  1819                WriteStr(fp, t->DataFormat[i]);
  1820                WriteStr(fp, ((i == (nSamples-1)) ? "\n" : "\t"));
  1821            }
  1822
  1823         WriteStr (fp, "END_DATA_FORMAT\n");
  1824  }
