  1826
  1827  // Writes data array
  1828  static
  1829  void WriteData(SAVESTREAM* fp, cmsIT8* it8)
  1830  {
  1831         int  i, j;
  1832         TABLE* t = GetTable(it8);
  1833
  1834         if (!t->Data) return;
  1835
  1836         WriteStr (fp, "BEGIN_DATA\n");
  1837
  1838         t->nPatches = satoi(cmsIT8GetProperty(it8, "NUMBER_OF_SETS"));
  1839
  1840         for (i = 0; i < t-> nPatches; i++) {
  1841
  1842                WriteStr(fp, " ");
  1843
  1844                for (j = 0; j < t->nSamples; j++) {
  1845
  1846                       char *ptr = t->Data[i*t->nSamples+j];
  1847
  1848                       if (ptr == NULL) WriteStr(fp, "\"\"");
  1849                       else {
  1850                           // If value contains whitespace, enclose within quote
  1851
  1852                           if (strchr(ptr, ' ') != NULL) {
  1853
  1854                               WriteStr(fp, "\"");
  1855                               WriteStr(fp, ptr);
  1856                               WriteStr(fp, "\"");
  1857                           }
  1858                           else
  1859                              WriteStr(fp, ptr);
  1860                       }
  1861
  1862                       WriteStr(fp, ((j == (t->nSamples-1)) ? "\n" : "\t"));
  1863                }
  1864         }
  1865         WriteStr (fp, "END_DATA\n");
  1866  }
