  1978  static
  1979  cmsBool DataSection (cmsIT8* it8)
  1980  {
  1981      int  iField = 0;
  1982      int  iSet   = 0;
  1983      char Buffer[256];
  1984      TABLE* t = GetTable(it8);
  1985
  1986      InSymbol(it8);   // Eats "BEGIN_DATA"
  1987      CheckEOLN(it8);
  1988
  1989      if (!t->Data)
  1990          AllocateDataSet(it8);
  1991
  1992      while (it8->sy != SEND_DATA && it8->sy != SEOF)
  1993      {
  1994          if (iField >= t -> nSamples) {
  1995              iField = 0;
  1996              iSet++;
  1997
  1998          }
  1999
  2000          if (it8->sy != SEND_DATA && it8->sy != SEOF) {
  2001
  2002              switch (it8->sy)
  2003              {
  2004
  2005              // To keep very long data
  2006              case SIDENT:
  2007                  if (!SetData(it8, iSet, iField, StringPtr(it8->id)))
  2008                      return FALSE;
  2009                  break;
  2010
  2011              case SSTRING:
  2012                  if (!SetData(it8, iSet, iField, StringPtr(it8->str)))
  2013                      return FALSE;
  2014                  break;
  2015
  2016              default:
  2017
  2018              if (!GetVal(it8, Buffer, 255, "Sample data expected"))
  2019                  return FALSE;
  2020
  2020
  2021              if (!SetData(it8, iSet, iField, Buffer))
  2022                  return FALSE;
  2023              }
  2024
  2025              iField++;
  2026
  2027              InSymbol(it8);
  2028              SkipEOLN(it8);
  2029          }
  2030      }
  2031
  2032      SkipEOLN(it8);
  2033      Skip(it8, SEND_DATA);
  2034      SkipEOLN(it8);
  2035
  2036      // Check for data completion.
  2037
  2038      if ((iSet+1) != t -> nPatches)
  2039          return SynError(it8, "Count mismatch. NUMBER_OF_SETS was %d, found %d\n", t ->nPatches, iSet+1);
  2040
  2041      return TRUE;
  2042  }
