  2047  static
  2048  cmsBool HeaderSection(cmsIT8* it8)
  2049  {
  2050      char VarName[MAXID];
  2051      char Buffer[MAXSTR];
  2052      KEYVALUE* Key;
  2053
  2054          while (it8->sy != SEOF &&
  2055                 it8->sy != SSYNERROR &&
  2056                 it8->sy != SBEGIN_DATA_FORMAT &&
  2057                 it8->sy != SBEGIN_DATA) {
  2058
  2059
  2060          switch (it8 -> sy) {
  2061
  2062          case SKEYWORD:
  2063                  InSymbol(it8);
  2064                  if (!GetVal(it8, Buffer, MAXSTR-1, "Keyword expected")) return FALSE;
  2065                  if (!AddAvailableProperty(it8, Buffer, WRITE_UNCOOKED)) return FALSE;
  2066                  InSymbol(it8);
  2067                  break;
  2068
  2069
  2070          case SDATA_FORMAT_ID:
  2071                  InSymbol(it8);
  2072                  if (!GetVal(it8, Buffer, MAXSTR-1, "Keyword expected")) return FALSE;
  2073                  if (!AddAvailableSampleID(it8, Buffer)) return FALSE;
  2074                  InSymbol(it8);
  2075                  break;
  2076
  2077
  2078          case SIDENT:
  2079              strncpy(VarName, StringPtr(it8->id), MAXID - 1);
  2080              VarName[MAXID - 1] = 0;
  2081
  2082              if (!IsAvailableOnList(it8->ValidKeywords, VarName, NULL, &Key)) {
  2083
  2084  #ifdef CMS_STRICT_CGATS
  2085                  return SynError(it8, "Undefined keyword '%s'", VarName);
  2086  #else
  2087                  Key = AddAvailableProperty(it8, VarName, WRITE_UNCOOKED);
  2088                  if (Key == NULL) return FALSE;
  2089  #endif
  2090              }
  2091
  2092              InSymbol(it8);
  2093              if (!GetVal(it8, Buffer, MAXSTR - 1, "Property data expected")) return FALSE;
  2094
  2095              if (Key->WriteAs != WRITE_PAIR) {
  2096                  AddToList(it8, &GetTable(it8)->HeaderList, VarName, NULL, Buffer,
  2097                      (it8->sy == SSTRING) ? WRITE_STRINGIFY : WRITE_UNCOOKED);
  2098              }
  2099              else {
  2100                  const char *Subkey;
  2101                  char *Nextkey;
  2102                  if (it8->sy != SSTRING)
  2103                      return SynError(it8, "Invalid value '%s' for property '%s'.", Buffer, VarName);
  2104
  2105                  // chop the string as a list of "subkey, value" pairs, using ';' as a separator
  2106                  for (Subkey = Buffer; Subkey != NULL; Subkey = Nextkey)
  2107                  {
  2108                      char *Value, *temp;
  2109
  2110                      //  identify token pair boundary
  2111                      Nextkey = (char*)strchr(Subkey, ';');
  2112                      if (Nextkey)
  2113                          *Nextkey++ = '\0';
  2114
  2115                      // for each pair, split the subkey and the value
  2116                      Value = (char*)strrchr(Subkey, ',');
  2117                      if (Value == NULL)
  2118                          return SynError(it8, "Invalid value for property '%s'.", VarName);
  2119
  2120                      // gobble the spaces before the coma, and the coma itself
  2121                      temp = Value++;
  2122                      do *temp-- = '\0'; while (temp >= Subkey && *temp == ' ');
