  1234  static
  1235  KEYVALUE* AddToList(cmsIT8* it8, KEYVALUE** Head, const char *Key, const char *Subkey, const char* xValue, WRITEMODE WriteAs)
  1236  {
  1237      KEYVALUE* p;
  1238      KEYVALUE* last;
  1239
  1240
  1241      // Check if property is already in list
  1242
  1243      if (IsAvailableOnList(*Head, Key, Subkey, &p)) {
  1244
  1245          // This may work for editing properties
  1246
  1247          //     return SynError(it8, "duplicate key <%s>", Key);
  1248      }
  1249      else {
  1250
  1251          last = p;
  1252
  1253          // Allocate the container
  1254          p = (KEYVALUE*) AllocChunk(it8, sizeof(KEYVALUE));
  1255          if (p == NULL)
  1256          {
  1257              SynError(it8, "AddToList: out of memory");
  1258              return NULL;
  1259          }
  1260
  1261          // Store name and value
  1262          p->Keyword = AllocString(it8, Key);
  1263          p->Subkey = (Subkey == NULL) ? NULL : AllocString(it8, Subkey);
  1264
  1265          // Keep the container in our list
  1266          if (*Head == NULL) {
  1267              *Head = p;
  1268          }
  1269          else
  1270          {
  1271              if (Subkey != NULL && last != NULL) {
  1272
  1273                  last->NextSubkey = p;
  1274
  1275                  // If Subkey is not null, then last is the last property with the same key,
  1276                  // but not necessarily is the last property in the list, so we need to move
  1277                  // to the actual list end
  1278                  while (last->Next != NULL)
  1279                           last = last->Next;
  1280              }
  1281
  1282              if (last != NULL) last->Next = p;
  1283          }
  1284
  1285          p->Next    = NULL;
  1286          p->NextSubkey = NULL;
  1287      }
  1288
  1289      p->WriteAs = WriteAs;
  1290
  1291      if (xValue != NULL) {
  1292
  1293          p->Value   = AllocString(it8, xValue);
  1294      }
  1295      else {
  1296          p->Value   = NULL;
  1297      }
  1298
  1299      return p;
  1300  }
